package io.github.aerialist7.page

import emotion.styled.styled
import io.github.aerialist7.router.SHOWCASE_ID_PARAM
import io.github.aerialist7.router.SHOWCASE_ROUTE_PATH
import io.github.aerialist7.router.useShowcaseIdParam
import io.github.aerialist7.selected
import io.github.aerialist7.showcase.Showcase
import io.github.aerialist7.speedDialAriaLabel
import js.array.ReadonlyArray
import js.objects.recordOf
import mui.material.*
import mui.system.Box
import mui.system.sx
import react.*
import react.dom.html.ReactHTML
import tanstack.react.router.Link
import tanstack.react.router.useLoaderData
import web.cssom.Color
import web.cssom.None
import web.cssom.Position
import web.cssom.px
import mui.icons.material.Menu as MenuIcon

val Sidebar = FC<Props> {
    val isMobile = useIsMobile()
    var isOpen by useState(false)

    Box {
        if (!isMobile) {
            sx {
                gridArea = Area.Sidebar
            }
        }

        component = ReactHTML.nav

        if (isMobile) {
            SwipeableDrawer {
                anchor = DrawerAnchor.left
                open = isOpen
                onOpen = { isOpen = true }
                onClose = { isOpen = false }

                ShowcaseList {
                    onSelect = { isOpen = false }
                }
            }

            SpeedDial {
                sx {
                    position = Position.absolute
                    bottom = 80.px
                    left = 16.px
                }

                speedDialAriaLabel = "Menu"

                icon = MenuIcon.create()
                onClick = { isOpen = true }
            }
        } else {
            Drawer {
                variant = DrawerVariant.permanent
                anchor = DrawerAnchor.left

                ShowcaseList()
            }
        }
    }
}

private external interface ShowcaseListProps : Props {
    var onSelect: (() -> Unit)?
}

private val ShowcaseList = FC<ShowcaseListProps> { props ->
    val showcases = useLoaderData { it.unsafeCast<ReadonlyArray<Showcase>>() }
    val showcaseId = useShowcaseIdParam()

    Box {
        Toolbar()

        List {
            sx {
                width = Sizes.Sidebar.Width
            }

            for ((key, name) in showcases) {
                LinkButton {
                    this.key = Key(key)
                    to = SHOWCASE_ROUTE_PATH
                    params = recordOf(SHOWCASE_ID_PARAM to key)

                    ListItemButton {
                        selected = showcaseId == key
                        onClick = { props.onSelect?.invoke() }

                        ListItemText {
                            primary = ReactNode(name)
                        }
                    }
                }
            }
        }
    }
}

private val LinkButton = Link.styled {
    textDecoration = None.none
    color = Color.currentColor
}
